using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageThirtySpecs
{
    private static void Assert(bool ok,string text){if(!ok)throw new Exception(text);}
    internal static GameState Ready()
    {
        var s=StageTwentySixSpecs.Fixture();foreach(var r in s.Relations)r.Trust=90;s.Player.Gold=10000;s.Player.Research="";s.ContinueAfterVictory=true;
        foreach(var c in s.Cities)c.Food=500;
        var home=s.Cities[0];home.Buildings.Add("warehouse");home.MarketStocks[TradeGood.Iron]=140;home.MarketStocks[TradeGood.Dyes]=80;
        Assert(Manufacturing.SetPolicy(s,home.Id,CraftRecipe.Tools,50).Success,"Policy failed");return s;
    }
    private static void Resolve(GameState s)
    {
        if(s.PendingEvent==null)return;var e=ProvincialEvents.Current(s);
        int i=Enumerable.Range(0,e.Choices.Length).First(i=>s.Player.Gold+e.Choices[i].Gold>=0);Assert(Narrative.Resolve(s,i).Success,"Council failed");
    }
    internal static void Step(GameState s){Resolve(s);s.Ending=null;Assert(Engine.EndTurn(s).Success,"Economic phase failed");Resolve(s);}
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    private static GameState Complete(InvestmentFunding mode)
    {var s=Ready();Assert(IndustrialInvestment.Begin(s,s.Cities[0].Id,CraftRecipe.Tools,mode).Success,"Signature failed");for(int i=0;i<8;i++)Step(s);Assert(s.Cities[0].Factory.Level==1,"Goal failed");return s;}
    public static void Run(Action<string,Action> test)
    {
        test("Industrial terms and rejected signatures preserve the campaign",()=>{var s=Ready();s.Player.Gold=0;string before=SaveGame.Serialize(s);Assert(IndustrialInvestment.Error(s,s.Cities[0],CraftRecipe.Tools,InvestmentFunding.Public)!=null&&!IndustrialInvestment.Begin(s,s.Cities[0].Id,CraftRecipe.Tools,InvestmentFunding.Public).Success,"Unaffordable signature accepted");Assert(SaveGame.Serialize(s)==before,"Rejected signature mutated state");});
        test("Signing pays the selected funding cost without instant machinery or goods",()=>{foreach(var mode in new[]{InvestmentFunding.Public,InvestmentFunding.Concession}){var s=Ready();var c=s.Cities[0];double gold=s.Player.Gold,stock=c.MarketStocks[TradeGood.Tools];Assert(IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,mode).Success,"Signing failed");Assert(s.Player.Gold==gold-IndustrialInvestment.Signature(mode)&&c.Factory.Level==0&&c.MarketStocks[TradeGood.Tools]==stock,"Instant upgrade or goods");Valid(s);}});
        test("Public investment uses eight real economic phases and paid batch evidence",()=>{var s=Complete(InvestmentFunding.Public);var p=s.Cities[0].Factory;Assert(p.Phases==8&&p.ProductivePhases>=4&&p.Batches>=6&&p.Spent==120+8*p.PhaseFee&&p.PeakLevel==1&&p.RoyaltyRemaining==0,"Invalid public outcome");Valid(s);});
        test("Equipment expands actual production while still requiring iron and work",()=>{var s=Complete(InvestmentFunding.Public);var c=s.Cities[0];var upgraded=Manufacturing.Quote(s,c,100);int limit=Manufacturing.Limit(s,c);c.Factory.Level=0;var baseline=Manufacturing.Quote(s,c,100);Assert(limit==Manufacturing.Limit(s,c)+1&&upgraded.Batches==baseline.Batches+1&&upgraded.Work>baseline.Work&&upgraded.Inputs.Sum(i=>i.Quantity)>baseline.Inputs.Sum(i=>i.Quantity),"Upgrade created free output or no throughput");});
        test("Buying finished stock does not fulfil an investment in idle workshops",()=>{var s=Ready();var c=s.Cities[0];c.ProductionPaused=true;c.MarketStocks[TradeGood.Tools]=50;int loyalty=c.Loyalty;IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public);for(int i=0;i<8;i++)Step(s);Assert(c.Factory.Level==0&&c.Factory.Batches==0&&c.Factory.ProductivePhases==0&&c.Loyalty<loyalty,"Purchased or idle goods counted");Valid(s);});
        test("Producing another recipe does not fulfil the signed objective",()=>{var s=Ready();var c=s.Cities[0];c.Buildings.Add(Manufacturing.Weavers);c.IndustryRecipe=CraftRecipe.Textiles;IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public);for(int i=0;i<8;i++)Step(s);Assert(c.Factory.Batches==0&&c.Factory.Level==0,"Wrong recipe credited");Valid(s);});
        test("No funds means no supervisor fee and no credited output",()=>{var s=Ready();var c=s.Cities[0];IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public);s.Player.Gold=0;c.LastIndustryTurn=s.Turn;c.LastIndustryRecipe=CraftRecipe.Tools;c.LastIndustryBatches=2;IndustrialInvestment.Tick(s);Assert(c.Factory.Phases==1&&c.Factory.Batches==0&&c.Factory.Spent==120&&s.Player.Gold==0,"Unfunded evidence counted");});
        test("An investment cannot charge or credit the same phase twice",()=>{var s=Ready();var c=s.Cities[0];IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public);IndustrialInvestment.Tick(s);string before=SaveGame.Serialize(s);IndustrialInvestment.Tick(s);Assert(SaveGame.Serialize(s)==before,"Duplicate phase mutated finances");});
        test("Concession completion starts future royalties without retroactive payment",()=>{var s=Complete(InvestmentFunding.Concession);var p=s.Cities[0].Factory;Assert(p.Level==1&&p.RoyaltyRemaining==24&&p.RoyaltyPaid==0&&p.PhaseFee==2&&p.Spent==46,"Concession paid early or grants free signatures");Step(s);Assert(p.RoyaltyRemaining==23&&p.RoyaltyPaid==p.RoyaltyFee,"Actual royalty not paid");Valid(s);});
        test("Missed royalties do not shorten the payment obligation",()=>{var s=Complete(InvestmentFunding.Concession);var p=s.Cities[0].Factory;s.Player.Gold=0;IndustrialInvestment.Tick(s);Assert(p.RoyaltyRemaining==24&&p.MissedRoyalties==1&&p.RoyaltyPaid==0,"Nonpayment shortened the obligation");s.Turn++;s.Player.Gold=100;IndustrialInvestment.Tick(s);Assert(p.RoyaltyRemaining==23&&p.MissedRoyalties==0&&p.RoyaltyPaid==p.RoyaltyFee,"Payment did not resume correctly");});
        test("Three consecutive missed royalties remove one equipment level exactly once",()=>{var s=Complete(InvestmentFunding.Concession);var c=s.Cities[0];for(int i=0;i<3;i++){s.Player.Gold=0;IndustrialInvestment.Tick(s);s.Turn++;}Assert(c.Factory.Level==0&&c.Factory.PeakLevel==1&&c.Factory.RoyaltyRemaining==0&&c.Factory.CapacityLostTurn>0,"Default did not reclaim equipment");int unrest=c.Unrest;IndustrialInvestment.Tick(s);Assert(c.Unrest==unrest&&c.Factory.Level==0,"Default repeated its penalties");Valid(s);});
        test("Paused production retains valid earlier throughput after repossession",()=>{var s=Complete(InvestmentFunding.Concession);var c=s.Cities[0];s.Player.Stability=100;s.Player.Focus=2;c.Focus=CityFocus.Industry;c.Unrest=0;c.Prosperity=c.Loyalty=100;Step(s);Assert(c.LastIndustryBatches>2,"Fixture did not use expanded throughput");c.ProductionPaused=true;for(int i=0;i<3;i++){s.Player.Gold=0;IndustrialInvestment.Tick(s);s.Turn++;}Assert(c.Factory.Level==0&&c.LastIndustryBatches>Manufacturing.Limit(s,c),"Fixture did not retain historical production");Valid(s);});
        test("Twenty four actual payments end a concession without removing equipment",()=>{var s=Complete(InvestmentFunding.Concession);var p=s.Cities[0].Factory;int fee=p.RoyaltyFee;for(int i=0;i<24;i++){s.Player.Gold=1000;Step(s);}Assert(p.Level==1&&p.RoyaltyRemaining==0&&p.RoyaltyPaid==24*fee,"Concession expiry wrong");Valid(s);});
        test("An active concession blocks another investment",()=>{var s=Complete(InvestmentFunding.Concession);s.Turn+=12;Assert(IndustrialInvestment.Error(s,s.Cities[0],CraftRecipe.Tools,InvestmentFunding.Public)!=null,"Concurrent concession accepted");});
        test("Cancellation is confirmed later without refunds or equipment",()=>{var s=Ready();var c=s.Cities[0];IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public);Assert(!IndustrialInvestment.Cancel(s,c.Id).Success,"Same-phase cancellation allowed");Step(s);double gold=s.Player.Gold;int unrest=c.Unrest;Assert(IndustrialInvestment.Cancel(s,c.Id).Success&&s.Player.Gold==gold&&c.Factory.Level==0&&c.Unrest==unrest+4,"Cancellation refunded or lost consequence");Valid(s);});
        test("Ownership preserves physical equipment and clears former obligations",()=>{var s=Complete(InvestmentFunding.Concession);var c=s.Cities[0];double gold=s.Factions[1].Gold;ProvincialPolitics.Transfer(s,c,1);Assert(c.Factory.Level==1&&c.Factory.RoyaltyRemaining==0&&c.Factory.Funding==InvestmentFunding.None&&s.Factions[1].Gold==gold,"Sovereignty inherited debt or lost equipment");Valid(s);});
        test("An active investment resumes deterministically after reload",()=>{var a=Ready();IndustrialInvestment.Begin(a,a.Cities[0].Id,CraftRecipe.Tools,InvestmentFunding.Public);for(int i=0;i<3;i++)Step(a);var b=SaveGame.Deserialize(SaveGame.Serialize(a));for(int i=0;i<5;i++){Step(a);Step(b);}Assert(SaveGame.Serialize(a)==SaveGame.Serialize(b),"Investment continuation diverged");});
        test("A signed concession resumes deterministically after reload",()=>{var a=Complete(InvestmentFunding.Concession);Step(a);var b=SaveGame.Deserialize(SaveGame.Serialize(a));Step(a);Step(b);Assert(SaveGame.Serialize(a)==SaveGame.Serialize(b),"Concession continuation diverged");});
        test("Unsupported owners recipes pending councils and legacy campaigns reject signing",()=>{var s=Ready();var c=s.Cities[0];Assert(!IndustrialInvestment.Begin(s,c.Id,(CraftRecipe)999,InvestmentFunding.Public).Success&&!IndustrialInvestment.Begin(s,s.Cities[1].Id,CraftRecipe.Tools,InvestmentFunding.Public).Success,"Invalid investment accepted");s.PendingEvent="founding";Assert(!IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public).Success,"Pending dialogue bypassed");s.PendingEvent=null;s.EpochCampaign=false;Assert(!IndustrialInvestment.Begin(s,c.Id,CraftRecipe.Tools,InvestmentFunding.Public).Success,"Legacy investment accepted");});
        test("Malformed fees missing evidence and overlarge equipment are rejected",()=>{foreach(string field in new[]{"Level","PeakLevel","Spent","Phases","Batches","RoyaltyRemaining","RoyaltyPaid"}){var s=Ready();IndustrialInvestment.Begin(s,s.Cities[0].Id,CraftRecipe.Tools,InvestmentFunding.Public);var j=JsonNode.Parse(SaveGame.Serialize(s))!;j["Cities"]![0]!["Factory"]![field]=999;bool rejected=false;try{SaveGame.Deserialize(j.ToJsonString());}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged "+field+" accepted");}});
        test("V27 migration invents no industry levels and keeps the exact predecessor",()=>{var s=Ready();var j=JsonNode.Parse(SaveGame.Serialize(s))!;j["Version"]=27;foreach(var city in j["Cities"]!.AsArray())city!.AsObject().Remove("Factory");string raw=j.ToJsonString(),path=Path.Combine(Path.GetTempPath(),"industry-v27-"+Guid.NewGuid()+".crown");try{File.WriteAllText(path,raw);var next=SaveGame.Read(path);Assert(next.Version==SaveGame.CurrentVersion&&next.Cities.All(c=>c.Factory.Level==0&&c.Factory.Funding==InvestmentFunding.None),"Migration invented machinery");SaveGame.Write(next,path);Assert(File.ReadAllText(path+".v27.bak")==raw,"Predecessor backup changed");}finally{if(File.Exists(path))File.Delete(path);if(File.Exists(path+".v27.bak"))File.Delete(path+".v27.bak");}});
    }
}
